function Invoke-ProAudioPhase($Session,[string]$Phase,$Guard,[string]$ProNonce,[string]$ScriptDirectory){
    $meta=$Guard.ReadCommand('audio-inputs.json')|ConvertFrom-Json
    if($meta.format -ne 1 -or $meta.proNonce -ne $ProNonce -or $meta.caseId -notmatch '^[a-f0-9]{32}$' -or $meta.supportCase -notmatch '^[a-f0-9]{32}$' -or $meta.zipSha256 -notmatch '^[a-f0-9]{64}$'){throw 'Bound Pro audio fixture required'}
    if($Phase -eq 'audio-stage'){
        $Guard.PinInputFile([string]$meta.zip);if((Get-FileHash -LiteralPath $meta.zip -Algorithm SHA256).Hash.ToLowerInvariant() -ne $meta.zipSha256){throw 'Audio payload changed'}
        if($meta.revision -notmatch '^[a-f0-9]{32}$'){throw 'Fresh audio payload revision required'}
        $policy=(Get-Command Assert-ProImageRetry -CommandType Function).ScriptBlock.ToString()
        Invoke-Command -Session $Session -ArgumentList $meta,$policy -ScriptBlock {param($meta,$policy) if((Get-Service vmms).Status -ne 'Running'){throw 'Ready Pro service required'};$all=@(Get-VM);if($meta.replaceApp){$prefix='C:\MuLab\public\audio-'+$meta.caseId;$config=[IO.File]::ReadAllText(('C:\MuLab\approved\audio-'+$meta.caseId+'-config.json'))|ConvertFrom-Json;$old=[IO.File]::ReadAllText(('C:\MuLab\approved\audio-'+$meta.caseId+'-result.json'))|ConvertFrom-Json;$owner=[IO.File]::ReadAllText($prefix+'-owner.json')|ConvertFrom-Json;$busy=@(Get-CimInstance Win32_Process|Where-Object{($_.ExecutablePath -and $_.ExecutablePath.StartsWith('C:\MuLab\',[StringComparison]::OrdinalIgnoreCase)) -or $_.ExecutablePath -like '*MuCodeSandbox-HyperVBroker-v1\bin\hv-broker-*.exe'}).Count;$root=Join-Path $env:ProgramData ('MuCodeSandbox-HyperVBroker-v1/users/'+$config.userSid);$ledger=[IO.File]::ReadAllText((Join-Path $root 'vms.json'))|ConvertFrom-Json;$paths=@();if($all.Count -eq 1){$paths=@(Get-VMHardDiskDrive -VM $all[0]|ForEach-Object{$_.Path})};&([ScriptBlock]::Create($policy)) $meta.caseId $old $owner ([bool]$busy) $all $ledger $paths $config.userSid $root|Out-Null}else{if($all.Count){throw 'Empty Pro guest required'}}}
        $archive='C:\MuLab\private\audio-'+$meta.caseId+'-'+$meta.revision+'.zip';Copy-Item -LiteralPath $meta.zip -Destination $archive -ToSession $Session
        return Invoke-Command -Session $Session -ArgumentList $meta,$archive -ScriptBlock {
            param($meta,$archive)
            $ErrorActionPreference='Stop';$target='C:\MuLab\audio-tools\'+$meta.caseId;$tools=$target
            if($meta.replaceApp){$tools='C:\MuLab\audio-tools\pending-'+$meta.caseId+'-'+$meta.revision}elseif(Test-Path -LiteralPath $tools){throw 'Existing audio payload must be inspected'}
            if(Test-Path -LiteralPath $tools){throw 'Pending audio revision already exists'}
            $support=[IO.File]::ReadAllText(('C:\MuLab\approved\image-'+$meta.supportCase+'-config.json'))|ConvertFrom-Json
            $expected='C:\MuLab\image-tools\'+$meta.supportCase;$node=Join-Path $expected 'product/resources/node/node.exe';$electron=Join-Path $expected 'electron/electron.exe'
            if($support.caseId -ne $meta.supportCase -or $support.tools -ne $expected -or $support.image -ne ('C:\MuLab\images\image-'+$meta.supportCase+'.vhdx') -or $support.imageSha256 -ne $meta.imageSha256 -or (Get-FileHash -LiteralPath $support.image -Algorithm SHA256).Hash.ToLowerInvariant() -ne $meta.imageSha256 -or (Get-FileHash -LiteralPath $node -Algorithm SHA256).Hash.ToLowerInvariant() -ne $meta.nodeSha256 -or (Get-FileHash -LiteralPath $electron -Algorithm SHA256).Hash.ToLowerInvariant() -ne $meta.electronSha256){throw 'Verified synthetic audio base/runtime reference changed'}
            if((Get-FileHash -LiteralPath $archive -Algorithm SHA256).Hash.ToLowerInvariant() -ne $meta.zipSha256){throw 'Transferred audio payload changed'}
            Add-Type -AssemblyName System.IO.Compression.FileSystem;$zip=[IO.Compression.ZipFile]::OpenRead($archive)
            try{[long]$size=0;if($zip.Entries.Count -gt 12000){throw 'Audio payload file count exceeded'};foreach($entry in $zip.Entries){$name=$entry.FullName.Replace('\','/');$size+=$entry.Length;if($size -gt 2GB -or $entry.Length -gt 128MB -or $name.Contains(':') -or $name.StartsWith('/') -or @($name.Split('/')|Where-Object{$_ -in @('.','..')}).Count -or (-not $name.StartsWith('app/') -and $name -notin @('pro-audio-client.mjs','pro-audio-electron.cjs','local-fixtures.mjs','fixture-key.pem','fixture-cert.pem'))){throw 'Unsafe audio payload entry'}}}finally{$zip.Dispose()}
            [IO.Compression.ZipFile]::ExtractToDirectory($archive,$tools);foreach($entry in $meta.files.psobject.Properties){if((Get-FileHash -LiteralPath (Join-Path $tools $entry.Name) -Algorithm SHA256).Hash.ToLowerInvariant() -ne $entry.Value){throw 'Audio staged file changed'}}
            if($meta.replaceApp){
                $before='C:\MuLab\audio-tools\before-'+$meta.caseId+'-'+$meta.revision;$parent=[IO.Path]::GetFullPath('C:\MuLab\audio-tools')
                foreach($path in @($target,$tools,$before)){if([IO.Path]::GetDirectoryName([IO.Path]::GetFullPath($path)) -ne $parent){throw 'Audio code move escaped its fixed test directory'}}
                foreach($path in @('C:\','C:\MuLab',$parent,$target,$tools)){if((Get-Item -LiteralPath $path).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Audio code reparse directory refused'}}
                if(Test-Path -LiteralPath $before){throw 'Existing audio code history preserved'}
                [IO.Directory]::Move($target,$before);try{[IO.Directory]::Move($tools,$target)}catch{if(-not(Test-Path -LiteralPath $target)){[IO.Directory]::Move($before,$target)};throw}
                $tools=$target
            }
            $config=@{caseId=$meta.caseId;proNonce=$meta.proNonce;tools=$tools;app=(Join-Path $tools 'app');support=$expected;node=$node;nodeSha256=$meta.nodeSha256;image=$support.image;imageSha256=$support.imageSha256;files=$meta.files;userSid=(Get-LocalUser MuLabUser).SID.Value}
            [IO.File]::WriteAllText(('C:\MuLab\approved\audio-'+$meta.caseId+'-config.json'),($config|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false));return @{complete=$true;staged=$true;desktopBaseReused=$true;audioStarted=$false}
        }
    }
    if($Phase -eq 'audio-refresh'){
        $hashes=@{};$sources=@{};foreach($name in @('pro-audio-client.mjs','pro-audio-electron.cjs')){$file=Join-Path $ScriptDirectory $name;$Guard.PinInputFile($file);$sources[$name]=$file;$hashes[$name]=(Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash.ToLowerInvariant()}
        $policy=(Get-Command Assert-ProImageRetry -CommandType Function).ScriptBlock.ToString()
        $plan=Invoke-Command -Session $Session -ArgumentList $meta.caseId,$policy -ScriptBlock {
            param($caseId,$policy)
            $prefix='C:\MuLab\public\audio-'+$caseId;$config=[IO.File]::ReadAllText(('C:\MuLab\approved\audio-'+$caseId+'-config.json'))|ConvertFrom-Json
            if((Get-ScheduledTask -TaskName ('MuPro-audio-'+$caseId) -ErrorAction SilentlyContinue) -or $config.caseId -ne $caseId){throw 'Existing audio task must be inspected'}
            $busy=@(Get-CimInstance Win32_Process|Where-Object{($_.ExecutablePath -and $_.ExecutablePath.StartsWith('C:\MuLab\',[StringComparison]::OrdinalIgnoreCase)) -or $_.ExecutablePath -like '*MuCodeSandbox-HyperVBroker-v1\bin\hv-broker-*.exe'}).Count;$all=@(Get-VM);$retry=$null;$old=$null
            if(Test-Path -LiteralPath ($prefix+'-owner.json')){$old=[IO.File]::ReadAllText(('C:\MuLab\approved\audio-'+$caseId+'-result.json'))|ConvertFrom-Json;$owner=[IO.File]::ReadAllText($prefix+'-owner.json')|ConvertFrom-Json;$root=Join-Path $env:ProgramData ('MuCodeSandbox-HyperVBroker-v1/users/'+$config.userSid);$ledger=[IO.File]::ReadAllText((Join-Path $root 'vms.json'))|ConvertFrom-Json;$paths=@();if($all.Count -eq 1){$paths=@(Get-VMHardDiskDrive -VM $all[0]|ForEach-Object{$_.Path})};$retry=&([ScriptBlock]::Create($policy)) $caseId $old $owner ([bool]$busy) $all $ledger $paths $config.userSid $root}elseif($busy -or $all.Count -or (Test-Path -LiteralPath ($prefix+'-result.json'))){throw 'Only unused or verified terminal stopped audio diagnostics may refresh'}
            foreach($name in @('pro-audio-client.mjs','pro-audio-electron.cjs')){if((Get-FileHash -LiteralPath (Join-Path $config.tools $name) -Algorithm SHA256).Hash.ToLowerInvariant() -ne $config.files.$name){throw 'Protected audio diagnostic changed'}};return @{tools=$config.tools;retry=$retry;oldNonce=$old.nonce;oldPid=$old.pid}
        }
        if($plan.tools -ne ('C:\MuLab\audio-tools\'+$meta.caseId)){throw 'Audio destination changed'};foreach($name in @('pro-audio-client.mjs','pro-audio-electron.cjs')){Copy-Item -LiteralPath $sources[$name] -Destination (Join-Path $plan.tools $name) -ToSession $Session -Force}
        return Invoke-Command -Session $Session -ArgumentList $meta.caseId,$hashes,$plan -ScriptBlock {
            param($caseId,$hashes,$plan)
            $file='C:\MuLab\approved\audio-'+$caseId+'-config.json';$config=[IO.File]::ReadAllText($file)|ConvertFrom-Json
            foreach($name in @('pro-audio-client.mjs','pro-audio-electron.cjs')){if((Get-FileHash -LiteralPath (Join-Path $config.tools $name) -Algorithm SHA256).Hash.ToLowerInvariant() -ne $hashes[$name]){throw 'Audio diagnostic refresh differs'};$config.files.$name=$hashes[$name]}
            if($plan.retry){$prefix='C:\MuLab\public\audio-'+$caseId;$old=[IO.File]::ReadAllText($prefix+'-result.json')|ConvertFrom-Json;if($old.nonce -cne $plan.oldNonce -or $old.pid -ne $plan.oldPid -or $old.complete -ne $false){throw 'Failed audio receipt changed'};$history='C:\MuLab\private\audio-history-'+$caseId+'-'+[guid]::NewGuid().ToString('N');New-Item -ItemType Directory -Path $history|Out-Null;foreach($name in @('owner.json','result.json','progress.json','launch.json','client.log','ui.png','ui-playing.png')){$from=[IO.Path]::GetFullPath($prefix+'-'+$name);$to=[IO.Path]::GetFullPath((Join-Path $history $name));if([IO.Path]::GetDirectoryName($from) -ne 'C:\MuLab\public' -or [IO.Path]::GetDirectoryName($to) -ne $history){throw 'Audio history boundary changed'};if(Test-Path -LiteralPath $from){[IO.File]::Move($from,$to)}};[IO.File]::Copy(('C:\MuLab\approved\audio-'+$caseId+'-result.json'),(Join-Path $history 'approved-result.json'));$config|Add-Member -NotePropertyName retryEnvironmentId -NotePropertyValue ([string]$plan.retry) -Force}
            [IO.File]::WriteAllText($file,($config|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false));return @{complete=$true;caseId=$caseId;hashes=$hashes;retryEnvironmentId=$plan.retry;productUnchanged=$true}
        }
    }
    $response=Invoke-Command -Session $Session -ArgumentList $meta.caseId,$Phase -ScriptBlock {
        param($caseId,$phase)
        $ErrorActionPreference='Stop';$prefix='C:\MuLab\public\audio-'+$caseId;$config=[IO.File]::ReadAllText(('C:\MuLab\approved\audio-'+$caseId+'-config.json'))|ConvertFrom-Json
        if($config.caseId -ne $caseId){throw 'Audio configuration changed'}
        if($phase -eq 'audio-inspect'){
            $reports=@();foreach($name in @('progress','result')){$file=$prefix+'-'+$name+'.json';if(Test-Path -LiteralPath $file){$reports+=[IO.File]::ReadAllText($file)|ConvertFrom-Json}}
            $logs=@();foreach($name in @('client','broker-error')){$file=$prefix+'-'+$name+'.log';if($name -eq 'broker-error'){$file='C:\MuLab\private\audio-'+$caseId+'-broker-error.log'};if(Test-Path -LiteralPath $file){$stream=[IO.File]::Open($file,[IO.FileMode]::Open,[IO.FileAccess]::Read,([IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete));try{$reader=[IO.StreamReader]::new($stream);$text=$reader.ReadToEnd();$logs+=@{name=$name;tail=$text.Substring([Math]::Max(0,$text.Length-5000))}}finally{$stream.Dispose()}}}
            $hashes=@{};foreach($name in @('server/platform/windows/audio','server/platform/windows/runtime','server/platform/windows/service','server/platform/windows/browser','server/guest-audio','shared/guest-audio')){$relative='dist-server/'+$name+'.js';$hashes[$relative]=(Get-FileHash (Join-Path $config.app $relative) -Algorithm SHA256).Hash.ToLowerInvariant()};$dist=Join-Path $config.app 'dist';foreach($file in @(Get-ChildItem -LiteralPath $dist -File -Recurse)){$relative='dist/'+$file.FullName.Substring($dist.Length+1).Replace('\','/');$hashes[$relative]=(Get-FileHash -LiteralPath $file.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}
            $audioChildren=@(Get-CimInstance Win32_Process -Filter "Name='ssh.exe'"|Where-Object{$_.CommandLine -like ('*'+$caseId+'*') -and $_.CommandLine -like '*mu_browser.monitor*'}|Select-Object ProcessId,CreationDate);$release=[IO.File]::ReadAllText((Join-Path $config.app 'dist-server/windows-release.json'))|ConvertFrom-Json;return @{complete=$true;caseId=$caseId;reports=$reports;logs=$logs;artifactHashes=$hashes;audioChildren=$audioChildren;release=$release;diagnosticHashes=@{'pro-audio-client.mjs'=(Get-FileHash (Join-Path $config.tools 'pro-audio-client.mjs')).Hash.ToLowerInvariant();'pro-audio-electron.cjs'=(Get-FileHash (Join-Path $config.tools 'pro-audio-electron.cjs')).Hash.ToLowerInvariant()};nodes=@(Get-CimInstance Win32_Process|Where-Object{$_.ExecutablePath -eq $config.node -or $_.ExecutablePath -eq (Join-Path $config.support 'electron/electron.exe')}|Select-Object ProcessId,CreationDate,CommandLine);nested=@(Get-VM|ForEach-Object{@{name=$_.Name;id=[string]$_.Id;state=[string]$_.State}})}
        }
        if($phase -ne 'audio-run' -or (-not $config.retryEnvironmentId -and @(Get-VM).Count) -or (Get-Service vmms).Status -ne 'Running'){throw 'Empty Pro guest or a verified stopped audio fixture required'}
        $ownerFile=$prefix+'-owner.json';$resultFile=$prefix+'-result.json';$task='MuPro-audio-'+$caseId
        if((Get-ScheduledTask -TaskName $task -ErrorAction SilentlyContinue) -or (Test-Path -LiteralPath $ownerFile) -or (Test-Path -LiteralPath $resultFile)){throw 'Existing audio run must be inspected'}
        $client=Join-Path $config.tools 'pro-audio-client.mjs';if((Get-FileHash -LiteralPath $client -Algorithm SHA256).Hash.ToLowerInvariant() -ne $config.files.'pro-audio-client.mjs' -or (Get-FileHash -LiteralPath $config.node -Algorithm SHA256).Hash.ToLowerInvariant() -ne $config.nodeSha256){throw 'Audio client/runtime changed'}
        $launch='$env:PSModulePath=Join-Path $PSHOME ''Modules''; & '''+$config.node+''' --no-warnings '''+$client+''' '+$caseId+' *> '''+$prefix+'-client.log'';exit $LASTEXITCODE';$encoded=[Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($launch));$principal=New-ScheduledTaskPrincipal -UserId 'MU-PRO-LAB\MuLabUser' -LogonType Interactive -RunLevel Limited;$action=New-ScheduledTaskAction -Execute (Join-Path $env:SystemRoot 'System32/WindowsPowerShell/v1.0/powershell.exe') -Argument ('-NoProfile -NonInteractive -WindowStyle Hidden -EncodedCommand '+$encoded) -WorkingDirectory C:\MuLab\public;$settings=New-ScheduledTaskSettingsSet -ExecutionTimeLimit ([TimeSpan]::FromHours(1)) -MultipleInstances IgnoreNew -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries;Register-ScheduledTask -TaskName $task -Action $action -Principal $principal -Settings $settings|Out-Null;Start-ScheduledTask -TaskName $task
        $until=[DateTime]::UtcNow.AddMinutes(3);while(-not(Test-Path -LiteralPath $ownerFile)){if([DateTime]::UtcNow -gt $until){throw 'Audio client has not started; keep its task for inspection'};Start-Sleep -Milliseconds 200};$owner=[IO.File]::ReadAllText($ownerFile)|ConvertFrom-Json;$process=Get-CimInstance Win32_Process -Filter ('ProcessId='+[int]$owner.pid)
        if($owner.caseId -ne $caseId -or $owner.nonce -notmatch '^[a-f0-9]{64}$' -or $process.ExecutablePath -ne $config.node -or (Invoke-CimMethod -InputObject $process -MethodName GetOwnerSid).Sid -ne $config.userSid){throw 'Audio owner binding changed'};$handle=Get-Process -Id $owner.pid;$null=$handle.Handle;$bin=Join-Path $env:ProgramData 'MuCodeSandbox-HyperVBroker-v1/bin';$artifact=[IO.File]::ReadAllText((Join-Path $bin 'current.json'))|ConvertFrom-Json;$broker=Join-Path $bin $artifact.brokerFile;if((Get-FileHash -LiteralPath $broker -Algorithm SHA256).Hash.ToLowerInvariant() -ne $artifact.brokerSha256){throw 'Protected audio broker changed'}
        $agent=Start-Process -FilePath $broker -ArgumentList @('--owner',[string]$owner.pid,'--pipe',[string]$owner.nonce,'--detect-host') -WorkingDirectory $bin -WindowStyle Hidden -RedirectStandardOutput ('C:\MuLab\private\audio-'+$caseId+'-broker-out.log') -RedirectStandardError ('C:\MuLab\private\audio-'+$caseId+'-broker-error.log') -PassThru;$until=[DateTime]::UtcNow.AddMinutes(25)
        do{if(Test-Path -LiteralPath $resultFile){$result=[IO.File]::ReadAllText($resultFile)|ConvertFrom-Json;if($result.pid -ne $owner.pid -or $result.nonce -cne $owner.nonce -or $result.caseId -ne $caseId){throw 'Audio result owner changed'};[IO.File]::WriteAllText(('C:\MuLab\approved\audio-'+$caseId+'-result.json'),($result|ConvertTo-Json -Depth 16),[Text.UTF8Encoding]::new($false));Unregister-ScheduledTask -TaskName $task -Confirm:$false;return $result};if($handle.HasExited){throw 'Audio client terminated without a result; retain resources and logs'};if([DateTime]::UtcNow -gt $until){throw 'Audio run remains unconfirmed; inspect before retrying'};Start-Sleep -Milliseconds 250}while($true)
    }
    if($Phase -eq 'audio-inspect'){foreach($kind in @('ui','ui-playing')){$encoded=Invoke-Command -Session $Session -ArgumentList $meta.caseId,$kind -ScriptBlock {param($caseId,$kind) $config=[IO.File]::ReadAllText(('C:\MuLab\approved\audio-'+$caseId+'-config.json'))|ConvertFrom-Json;$file='C:\MuLab\public\audio-'+$caseId+'-'+$kind+'.png';if(-not(Test-Path -LiteralPath $file)){return $null};$info=Get-Item -LiteralPath $file;if($info.PSIsContainer -or $info.Length -gt 10MB -or $info.Length -lt 33 -or ($info.Attributes -band [IO.FileAttributes]::ReparsePoint) -or [IO.File]::GetAccessControl($file).GetOwner([Security.Principal.SecurityIdentifier]).Value -ne $config.userSid){throw 'Synthetic audio screenshot invalid'};$bytes=[IO.File]::ReadAllBytes($file);if([Convert]::ToBase64String($bytes[0..7]) -ne 'iVBORw0KGgo='){throw 'Audio screenshot is not PNG'};return [Convert]::ToBase64String($bytes)};if($encoded){$file=$Guard.Reserve('audio-ui-'+[guid]::NewGuid().ToString('N')+'.png');[IO.File]::WriteAllBytes($file,[Convert]::FromBase64String($encoded));$response[$(if($kind -eq 'ui'){'screenshot'}else{'playingScreenshot'})]=$file}}}
    return $response
}
